import{_ as n,o as i,c as e,a3 as t}from"./chunks/framework.BvvarXmc.js";const h=JSON.parse('{"title":"Bantuan & Pertanyaan Umum (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":null}'),u={name:"faq/index.md"};function r(s,a,l,k,o,m){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="bantuan-pertanyaan-umum-faq" tabindex="-1">Bantuan &amp; Pertanyaan Umum (FAQ) <a class="header-anchor" href="#bantuan-pertanyaan-umum-faq" aria-label="Permalink to &quot;Bantuan &amp; Pertanyaan Umum (FAQ)&quot;">​</a></h1><p>Berikut adalah jawaban atas pertanyaan dan kendala yang paling sering ditanyakan oleh guru, wali murid, dan staf sekolah.</p><hr><h3 id="_1-bagaimana-jika-siswa-atau-orang-tua-lupa-kata-sandi-password" tabindex="-1">1. Bagaimana jika siswa atau orang tua lupa kata sandi (password)? <a class="header-anchor" href="#_1-bagaimana-jika-siswa-atau-orang-tua-lupa-kata-sandi-password" aria-label="Permalink to &quot;1. Bagaimana jika siswa atau orang tua lupa kata sandi (password)?&quot;">​</a></h3><blockquote><p><strong>Solusi:</strong> Siswa atau orang tua cukup menghubungi <strong>Wali Kelas</strong> atau staf <strong>Tata Usaha (TU)</strong> sekolah. Admin TU dapat mereset kata sandi melalui menu <em>Kelola Pengguna Reset Password</em>.</p></blockquote><hr><h3 id="_2-bagaimana-jika-transfer-virtual-account-spp-sudah-berhasil-didebit-dari-bank-namun-status-di-aplikasi-belum-berubah-jadi-lunas" tabindex="-1">2. Bagaimana jika transfer Virtual Account SPP sudah berhasil didebit dari bank, namun status di aplikasi belum berubah jadi &quot;LUNAS&quot;? <a class="header-anchor" href="#_2-bagaimana-jika-transfer-virtual-account-spp-sudah-berhasil-didebit-dari-bank-namun-status-di-aplikasi-belum-berubah-jadi-lunas" aria-label="Permalink to &quot;2. Bagaimana jika transfer Virtual Account SPP sudah berhasil didebit dari bank, namun status di aplikasi belum berubah jadi &quot;LUNAS&quot;?&quot;">​</a></h3><blockquote><p><strong>Solusi:</strong></p><ul><li>Umumnya notifikasi bank masuk dalam hitungan detik. Namun jika ada gangguan jaringan antar-bank, tunggu maksimal 5–10 menit lalu muat ulang (<em>refresh</em>) halaman tagihan.</li><li>Jika dalam 15 menit status belum berubah, simpan bukti transfer / struk ATM, lalu konfirmasikan ke Bendahara Sekolah untuk dilakukan pencocokan data nomor referensi transaksi.</li></ul></blockquote><hr><h3 id="_3-apa-yang-harus-dilakukan-jika-kartu-pelajar-smart-card-hilang" tabindex="-1">3. Apa yang harus dilakukan jika Kartu Pelajar (Smart Card) hilang? <a class="header-anchor" href="#_3-apa-yang-harus-dilakukan-jika-kartu-pelajar-smart-card-hilang" aria-label="Permalink to &quot;3. Apa yang harus dilakukan jika Kartu Pelajar (Smart Card) hilang?&quot;">​</a></h3><blockquote><p><strong>Solusi:</strong></p><ol><li>Segera buka portal siswa melalui HP/laptop, lalu pilih menu <strong>Dompet Digital Bekukan Kartu Sementara</strong> agar saldo uang jajan di kartu tidak bisa dipakai oleh orang lain.</li><li>Laporkan ke staf Tata Usaha (TU) sekolah untuk pencetakan kartu fisik pengganti. Saldo yang tersisa di akun lama akan otomatis berpindah ke kartu yang baru.</li></ol></blockquote><hr><h3 id="_4-bisakah-satu-orang-tua-memantau-lebih-dari-satu-anak-jika-memiliki-2-anak-di-sekolah-yang-sama" tabindex="-1">4. Bisakah satu orang tua memantau lebih dari satu anak jika memiliki 2 anak di sekolah yang sama? <a class="header-anchor" href="#_4-bisakah-satu-orang-tua-memantau-lebih-dari-satu-anak-jika-memiliki-2-anak-di-sekolah-yang-sama" aria-label="Permalink to &quot;4. Bisakah satu orang tua memantau lebih dari satu anak jika memiliki 2 anak di sekolah yang sama?&quot;">​</a></h3><blockquote><p><strong>Solusi:</strong><strong>Bisa.</strong> Akun wali murid dapat ditautkan ke beberapa nomor induk siswa (NISN) sekaligus. Di bagian atas portal akan muncul menu dropdown untuk beralih (<em>switch</em>) profil antara anak pertama dan anak kedua tanpa perlu login ulang.</p></blockquote><hr><h3 id="_5-bagaimana-jika-koneksi-internet-terputus-di-tengah-tengah-pengerjaan-ujian-online-cbt" tabindex="-1">5. Bagaimana jika koneksi internet terputus di tengah-tengah pengerjaan ujian online (CBT)? <a class="header-anchor" href="#_5-bagaimana-jika-koneksi-internet-terputus-di-tengah-tengah-pengerjaan-ujian-online-cbt" aria-label="Permalink to &quot;5. Bagaimana jika koneksi internet terputus di tengah-tengah pengerjaan ujian online (CBT)?&quot;">​</a></h3><blockquote><p><strong>Solusi:</strong> Jawaban yang sudah dipilih otomatis tersimpan di server (<em>auto-save</em>). Siswa tidak perlu panik:</p><ol><li>Sambungkan kembali gawai ke koneksi internet/WiFi.</li><li>Muat ulang halaman ujian atau minta pengawas mereset status sesi ujian jika browser terkunci.</li><li>Siswa dapat melanjutkan sisa waktu ujian tanpa kehilangan jawaban yang telah diisi sebelumnya.</li></ol></blockquote><hr><h3 id="_6-ke-mana-sekolah-menghubungi-jika-memerlukan-bantuan-teknis-lebih-lanjut" tabindex="-1">6. Ke mana sekolah menghubungi jika memerlukan bantuan teknis lebih lanjut? <a class="header-anchor" href="#_6-ke-mana-sekolah-menghubungi-jika-memerlukan-bantuan-teknis-lebih-lanjut" aria-label="Permalink to &quot;6. Ke mana sekolah menghubungi jika memerlukan bantuan teknis lebih lanjut?&quot;">​</a></h3><blockquote><p><strong>Kontak Bantuan:</strong> Tim Layanan Bantuan Super Schools siap membantu melalui WhatsApp Support atau email resmi yang tertera pada bagian bawah dashboard aplikasi sekolah Anda.</p></blockquote>',20)])])}const g=n(u,[["render",r]]);export{h as __pageData,g as default};
